// Teleports a player unit to a new room/position (via PATH_CheckCollisionFlags) and, if the unit was in a movement mode, re-issues the appropriate walk/run PlayerMessage to resume movement toward the previous target unit or coordinates.
void __fastcall CLIENT_WarpPlayerAndContinueMove(D2UnitStrc * pUnit, D2RoomStrc * pRoom, uint16_t nNewX, uint16_t nNewY) {
    D2ServerMessageHandleStrc sMoveMessage;
    eD2PlayerAnimMode eAnimMode = pUnit->eAnimMode.ePlayerMode;
    D2DynamicPathStrc* local_18 = pUnit->pPath.pDynamicPath;
    D2UnitStrc* pTargetUnit = 0;
    int bWasMoveMode = 0;
    int32_t nDestX = 0;
    int32_t nDestY = 0;
    D2RoomStrc* pTargetRoom = pRoom;
    if ((int)eAnimMode >= 2 && ((int)eAnimMode <= 3 || eAnimMode == TownWalk)) {
      bWasMoveMode = 1;
      pTargetUnit = CUnit::GetConfirmedTargetUnit(pUnit);
      if (!pTargetUnit) {
        SKILLS::Skills::GetCooordinates(pUnit, &nDestX, &nDestY);
      }
    }

    D2Common::PATH::Path::PATH_CheckCollisionFlags(local_18, (uint32_t)pUnit, pTargetRoom, nNewX, nNewY);
    if (!bWasMoveMode) {
      return;
    }

    sMoveMessage.nTargetUnitType = 0;
    sMoveMessage.nTargetUnitId = 0;
    sMoveMessage.nSkillLvl = 0;
    sMoveMessage.nMaxDistance = 0;
    sMoveMessage.nTargetX = 0;
    if (pTargetUnit) {
      sMoveMessage.nItemId = pTargetUnit->nUnitGUID;
      sMoveMessage.nSkillId = pTargetUnit->eUnitType;
      PlayerMessage(eAnimMode != eD2PlayerAnimMode_ns::Run ? 0 : 0x18, pUnit, &sMoveMessage, 0);
      return;
    }

    sMoveMessage.nItemId = nDestY;
    sMoveMessage.nSkillId = nDestX;
    PlayerMessage((eAnimMode != eD2PlayerAnimMode_ns::Run ? -22 : 0) + 0x17, pUnit, &sMoveMessage, 0);
}

// Client-side stamina-depletion handler for the local player. When the player's stamina hits 0, cancels any active run/walk: if chasing a unit target, re-issues a follow message; otherwise captures the current destination, frees any pending light map, resets the current skill, and transitions the unit to Walk or TownWalk mode (or falls back to CLIENT_SetAnimModeAndMoveToCurrentPos if no valid path target). No-ops for non-local or non-zero stamina units.
static void CLIENT_CancelRunAndWalk(D2UnitStrc * pUnit) {
    eD2PlayerAnimMode nAnimMode;
    eD2PlayerAnimMode eNeutralMode;
    D2ServerMessageHandleStrc nStaminaOrDestX;
    D2UnitStrc* pPlayerUnit_lcl = GetPlayerUnit_Net();
    if (pUnit != pPlayerUnit_lcl) {
      return;
    }

    nStaminaOrDestX.nSkillId = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(pUnit, UNITSTAT_stamina, 0);
    if (nStaminaOrDestX.nSkillId) {
      return;
    }

    D2DynamicPathStrc* pDynamicPath = pUnit->pPath.pDynamicPath;
    nStaminaOrDestX.nItemId = nStaminaOrDestX.nSkillId;
    nStaminaOrDestX.nTargetUnitType = nStaminaOrDestX.nSkillId;
    nStaminaOrDestX.nTargetUnitId = nStaminaOrDestX.nSkillId;
    nStaminaOrDestX.nSkillLvl = nStaminaOrDestX.nSkillId;
    nStaminaOrDestX.nMaxDistance = nStaminaOrDestX.nSkillId;
    nStaminaOrDestX.nTargetX = nStaminaOrDestX.nSkillId;
    pPlayerUnit_lcl = CUnit::GetConfirmedTargetUnit(pUnit);
    D2UnitStrc* pPathTargetUnit = D2Common::PATH::DynamicPath::GetTargetUnit(pDynamicPath);
    if (pPathTargetUnit) {
      nStaminaOrDestX.nSkillId = UNIT_COUNT;
      if (pPlayerUnit_lcl) {
        nStaminaOrDestX.nSkillId = pPlayerUnit_lcl->eUnitType;
        nStaminaOrDestX.nItemId = pPlayerUnit_lcl->nUnitGUID;
      } else {
        nStaminaOrDestX.nItemId = -1;
      }

      PlayerMessage(0, pUnit, &nStaminaOrDestX, 0);
      return;
    }

    nStaminaOrDestX.nSkillId = D2Common::PATH::DynamicPath::GetXSP1(pDynamicPath);
    nStaminaOrDestX.nItemId = D2Common::PATH::DynamicPath::GetYSP1(pDynamicPath);
    D2LightMapStrc* pLightMap = D2Common::Skills::SwapLightMap(pUnit, nullptr);
    if (pLightMap) {
      Draw::LightMap::FreeLightMap(pLightMap);
    }

    pPlayerUnit_lcl = GetPlayerUnit_UI();
    PLAYER_ApplyCurrentSkillFlags((uint32_t)(pUnit == pPlayerUnit_lcl), pUnit);
    D2Common::Units::SetCurrentSkill(pUnit, nullptr);
    if (pUnit->eAnimMode.ePlayerMode == KnockBack) {
      return;
    }

    D2Common::PATH::DynamicPath::PATH_RestoreVelocityAndPathType(pUnit->pPath.pDynamicPath);
    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    BOOL bRoomInTown = D2Common::DUNGEON::Dungeon::DRLGROOM_IsRoomInTown(pRoom);
    if (bRoomInTown) {
      eNeutralMode = TownNeutral;
      nAnimMode = TownWalk;
    } else {
      eNeutralMode = eD2PlayerAnimMode_ns::Neutral;
      nAnimMode = Walk;
    }

    uint32_t bTargetSet = Path::PATH_SetTargetAndCalculate(pUnit, (int16_t)nStaminaOrDestX.nSkillId, (int16_t)nStaminaOrDestX.nItemId);
    if (bTargetSet) {
      UnitMode::UNITMODE_SetAnimMode(pUnit, nAnimMode);
      return;
    }

    Engine::CLIENT_SetAnimModeAndMoveToCurrentPos(eNeutralMode, 1, pUnit);
}

